import { lazy, ReactNode, Suspense } from "react";
import { type LottieProps } from "react-lottie-player";

const Lottie = lazy(() => import("react-lottie-player/dist/LottiePlayerLight"));

export type Props = LottieProps & {
  fallback?: ReactNode;
};

/**
 * LottieAnimation is a wrapper component, used whenever we need a Lottie animation.
 *
 * This component makes sure we have consistent behaviour in these aspects:
 * 1. Always uses the light player
 * 2. Renders `fallback` during SSR/SSG, since the player only works client-side
 * 3. Lazy-loads the player on the client (with `fallback` shown while it loads)
 */
export const LottieAnimation = ({ fallback = null, ...props }: Props) => {
  if (typeof window === "undefined") return fallback;

  return (
    <Suspense fallback={fallback}>
      <Lottie {...props} />
    </Suspense>
  );
};
