import structure from "@/core/styling/structure.module.less";
import styles from "./text-block.module.less";
import { CallToAction, ExistingThemes } from "@/core/types";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { PrimaryButtonLink, buttonUrlFromCallToAction } from "@/core/components/primitives/parks-button/parks-button";
import { GatsbyImage, IGatsbyImageData, withArtDirection } from "gatsby-plugin-image";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import { exhaustiveCheck, multipleClassNames } from "@/core/helpers";
import { PropsWithChildren } from "react";
import { colord } from "colord";
import { LottieAnimation } from "@/core/components/primitives/lottie-animation/lottie-animation";

export type ImageField = {
  description: string;
  gatsbyImageData: IGatsbyImageData;
};

export type MediaPositioningTypes = "topLeft" | "topRight" | "bottomLeft" | "bottomRight";

export type ColorOverrides = {
  backgroundColor?: string;
  textColor?: string;
  headingColor?: string;
  neonColorBase?: string;
  neonColorShine?: string;

  linkColor?: string;
  shouldUnderlineLinks?: boolean;

  buttonTextColor?: string;
  buttonBackgroundColor?: string;

  expandContentButtonTextColor?: string;
  expandContentButtonBackgroundColor?: string;
  expandContentButtonBorderColor?: string;
};

export type Props = {
  contentfulId?: string;
  text?: {
    childMarkdownRemark: {
      html: string;
      excerpt: string;
    };
  };
  richText?: RichTextType;
  title?: string;
  readMoreLabel?: string;
  readLessLabel?: string;
  readMoreText?: {
    childMarkdownRemark: {
      html: string;
    };
  };
  callToActionButton?: CallToAction;
  quoteAuthor?: string;
  quoteLargeText?: boolean;
  borderPattern?: string;
  enableNeonHeading?: boolean;
  backgroundColor?: boolean;
  centerText?: boolean;
  imagePosition?: MediaPositioningTypes | "standard";
  componentTheme?: ExistingThemes;
  size?: "xs" | "s" | "m" | "l";
  image?: {
    xs: ImageField;
    s: ImageField;
    m: ImageField;
    l: ImageField;
    cornerMobile: ImageField;
    cornerDesktop: ImageField;
  };
  colorOverrides?: ColorOverrides;
  shouldFillOuterWrapper?: boolean;
  animationUrl?: string;
  animationPosition?: MediaPositioningTypes | "standard";
  /** Determined from site repo. Should follow the same pattern as the image data query */
  imagePixelWidth?: number;
};

export const TextBlock = ({
  contentfulId,
  text,
  richText,
  title,
  readMoreLabel,
  readLessLabel,
  readMoreText,
  callToActionButton,
  quoteAuthor,
  quoteLargeText,
  image,
  borderPattern,
  enableNeonHeading,
  backgroundColor,
  centerText,
  componentTheme,
  size,
  children,
  imagePosition = "standard",
  colorOverrides,
  shouldFillOuterWrapper = false,
  animationUrl,
  animationPosition = "standard",
  imagePixelWidth,
}: PropsWithChildren<Props>) => {
  const buttonUrl = buttonUrlFromCallToAction(callToActionButton);
  const borderPatterBackground = borderPattern
    ? ({
        "--dynamic-background": `url(${borderPattern})`,
      } as React.CSSProperties)
    : {};

  const imageDataStandard = getImageData(image, size);
  const imageDataCorner = getImageDataCorners(image);
  const isStandardImagePosition = imagePosition === "standard";
  const isStandardAnimationPosition = animationPosition === "standard";

  const hasCornerImage = imageDataCorner && !isStandardImagePosition;
  const hasCornerAnimation = !!animationUrl && !isStandardAnimationPosition;

  const hasImageInStandardPosition = !!imageDataStandard && isStandardImagePosition;
  const hasAnimationInStandardPosition = !!animationUrl && isStandardAnimationPosition;

  const styleOverrides = getStyleOverrides(colorOverrides);
  const shouldUnderlineLinks = colorOverrides?.shouldUnderlineLinks ?? true;

  const shouldRenderAnimation = !!animationUrl && !(image && animationPosition === imagePosition);

  return (
    <section className={multipleClassNames(componentTheme)} data-contentful-id={contentfulId} style={styleOverrides}>
      <div
        className={multipleClassNames(
          shouldFillOuterWrapper ? structure.blockFloatingPadding : structure.blockFloating,
          structure.blockRelative,
          styles.wrapper,
          borderPattern ? styles.borderPattern : "",
        )}
        style={borderPatterBackground}
        data-has-background-color={backgroundColor ? true : false}
        data-has-border-pattern={borderPattern ? true : false}
        data-border-pattern-url={borderPattern}
        data-position-image={!!image && imagePosition}
        data-position-animation={!!animationUrl && animationPosition}
        data-should-underline-links={shouldUnderlineLinks}
        data-should-fill-outer-wrapper={shouldFillOuterWrapper}
      >
        <div
          className={multipleClassNames(
            centerText && styles.centerText,
            getBlockMaxWidthStyleFromSizeProp(size),
            styles.innerWrapper,
          )}
          data-is-large-quote={quoteLargeText ? true : false}
          data-has-background-color={backgroundColor ? true : false}
          data-has-border-pattern={borderPattern ? true : false}
        >
          {hasCornerImage && <CornerMedia mediaPosition={imagePosition} imageDataCorner={imageDataCorner} />}
          {hasCornerAnimation && shouldRenderAnimation && (
            <CornerMedia mediaPosition={animationPosition} animationUrl={animationUrl} />
          )}
          {hasImageInStandardPosition && (
            <div className={styles.mediaStandardPositionWrapper}>
              <GatsbyImage image={imageDataStandard.gatsbyImageData} alt={imageDataStandard.description} />
            </div>
          )}
          {hasAnimationInStandardPosition && shouldRenderAnimation && (
            <div className={styles.mediaStandardPositionWrapper}>
              <LottieAnimation path={animationUrl} style={{ width: imagePixelWidth }} loop play />
            </div>
          )}

          <div className={styles.contentWrapper} data-has-background-color={backgroundColor ? true : false}>
            {title && (
              <h2
                className={styles.title}
                data-is-neon={enableNeonHeading}
                data-has-background-color={backgroundColor}
                data-has-image-over={!!imageDataStandard}
              >
                {title}
              </h2>
            )}
            {quoteAuthor && (
              <footer className={`${styles.quoteAuthor} ${quoteLargeText ? "h3" : ""}`}>{quoteAuthor}</footer>
            )}
            {text && (
              <div
                className={styles.markdownText}
                dangerouslySetInnerHTML={{ __html: text.childMarkdownRemark.html }}
                data-has-background-color={backgroundColor}
              ></div>
            )}
            {richText && <RichText richText={richText} />}
            {readMoreText && (
              <div className={styles.expandContentWrapper}>
                <ExpandContent showMoreLabelOverride={readMoreLabel} showLessLabelOverride={readLessLabel}>
                  <div dangerouslySetInnerHTML={{ __html: readMoreText.childMarkdownRemark.html }}></div>
                </ExpandContent>
              </div>
            )}
            {callToActionButton?.title && buttonUrl && (
              <PrimaryButtonLink
                className={`${styles.buttonWrapper} ${backgroundColor ? styles.buttonWrapperOnBackground : ""}`}
                url={buttonUrl}
                label={callToActionButton.title}
                openInNewTab={callToActionButton.openInNewTab}
              />
            )}
          </div>

          {children}
        </div>
      </div>
    </section>
  );
};

const CornerMedia = ({
  mediaPosition,
  imageDataCorner,
  animationUrl,
}: {
  mediaPosition: MediaPositioningTypes;
  imageDataCorner?: { images: IGatsbyImageData; description: string };
  animationUrl?: string;
}) => {
  return (
    <div
      data-position-image={mediaPosition}
      data-position-animation={mediaPosition}
      className={styles.imageCornerWrapper}
    >
      {imageDataCorner && (
        <GatsbyImage
          className={styles.gatsbyImage}
          image={imageDataCorner.images}
          alt={imageDataCorner.description}
          objectFit="contain"
        />
      )}
      {animationUrl && <LottieAnimation path={animationUrl} loop play className={styles.gatsbyImage} />}
    </div>
  );
};

const getBlockMaxWidthStyleFromSizeProp = (size: Props["size"]) => {
  if (size === undefined) return structure.blockMaxWidthM;
  switch (size) {
    case "xs":
      return structure.blockMaxWidthXs;
    case "s":
      return structure.blockMaxWidthS;
    case "m":
      return structure.blockMaxWidthM;
    case "l":
      return structure.blockMaxWidthL;
    default:
      return exhaustiveCheck(size);
  }
};

const getImageData = (image: Props["image"], size: Props["size"]) => {
  if (!image || size === undefined) return undefined;

  switch (size) {
    case "xs":
      return image.xs;
    case "s":
      return image.s;
    case "m":
      return image.m;
    case "l":
      return image.l;
    default:
      return exhaustiveCheck(size);
  }
};

const getImageDataCorners = (image: Props["image"]) => {
  if (!image || !image.cornerMobile || !image.cornerDesktop) return undefined;

  const images = withArtDirection(image.cornerMobile.gatsbyImageData, [
    {
      media: "(min-width: 64rem)",
      image: image.cornerDesktop.gatsbyImageData,
    },
  ]);

  return {
    images,
    description: image.cornerMobile.description,
  };
};

type OverridableCssVariables =
  | "--component-text-block-color-background"
  | "--component-text-block-text-color"
  | "--component-text-block-text-color-on-background"
  | "--component-text-block-title-color"
  | "--component-text-block-title-color-on-background"
  | "--component-text-block-neon-heading-color"
  | "--component-text-block-color-neon-base-1"
  | "--component-text-block-color-neon-base-2"
  | "--component-text-block-color-neon-shine"
  | "--common-color-link"
  | "--common-color-link-on-background"
  | "--component-primary-button-text"
  | "--component-primary-button-background"
  | "--component-primary-button-border"
  | "--component-primary-complementary-button-text"
  | "--component-primary-complementary-button-background"
  | "--component-primary-complementary-button-border";

type ColorOverridesKeys = Exclude<keyof ColorOverrides, "shouldUnderlineLinks">;

const overrideMapping = {
  backgroundColor: ["--component-text-block-color-background"],
  textColor: ["--component-text-block-text-color", "--component-text-block-text-color-on-background"],
  headingColor: [
    "--component-text-block-title-color",
    "--component-text-block-title-color-on-background",
    "--component-text-block-neon-heading-color",
  ],
  neonColorBase: ["--component-text-block-color-neon-base-1", "--component-text-block-color-neon-base-2"],
  neonColorShine: ["--component-text-block-color-neon-shine"],

  linkColor: ["--common-color-link", "--common-color-link-on-background"],

  buttonTextColor: ["--component-primary-button-text"],
  buttonBackgroundColor: ["--component-primary-button-background", "--component-primary-button-border"],

  expandContentButtonTextColor: ["--component-primary-complementary-button-text"],
  expandContentButtonBackgroundColor: ["--component-primary-complementary-button-background"],
  expandContentButtonBorderColor: ["--component-primary-complementary-button-border"],
} satisfies Record<ColorOverridesKeys, Array<OverridableCssVariables>>;

const neonBaseAlphas = {
  "--component-text-block-color-neon-base-1": 0.8,
  "--component-text-block-color-neon-base-2": 0.5,
};

export const getStyleOverrides = (colorOverrides: Props["colorOverrides"]) => {
  if (!colorOverrides) return {};

  const listOfAllKeysOfColorOverrides = Object.keys(overrideMapping) as Array<ColorOverridesKeys>;

  // A type for the object of the css variables that can be overriden and their new values
  const styleOverrides = {} as Record<OverridableCssVariables, string>;
  for (const key of listOfAllKeysOfColorOverrides) {
    const overrideValue = colorOverrides[key];
    if (!overrideValue) continue;

    for (const cssVariable of overrideMapping[key]) {
      if (
        cssVariable === "--component-text-block-color-neon-base-1" ||
        cssVariable === "--component-text-block-color-neon-base-2"
      ) {
        styleOverrides[cssVariable] = colord(overrideValue).alpha(neonBaseAlphas[cssVariable]).toRgbString();
        continue;
      }
      styleOverrides[cssVariable] = overrideValue;
    }
  }

  return styleOverrides as React.CSSProperties;
};
